        public static bool Existe(string nom)
        {
            return Traces.ContainsKey(nom);
        }

        /// <summary>Construit l'icône demandée (remplissage encre du chrome, nette à tous les DPI).</summary>
        public static Control Creer(string nom, double taille)
        {
            return Creer(nom, taille, Chrome.EncreIcone);
        }

        public static Control Creer(string nom, double taille, IBrush pinceau)
        {
            string donnees;
            if (!Traces.TryGetValue(nom, out donnees))
                return new TextBlock { Text = "?" };
            Path chemin = new Path();
            chemin.Data = Geometry.Parse(donnees);
            chemin.Fill = pinceau;
            chemin.Width = taille;
            chemin.Height = taille;
            chemin.Stretch = Stretch.Uniform;
            chemin.VerticalAlignment = VerticalAlignment.Center;
            chemin.HorizontalAlignment = HorizontalAlignment.Center;
            return chemin;
        }
    }
